  await assertLastOwnerRetained(input.orgId, input.memberId, input.role);
  await assertSeatAvailableForRole(input.orgId, member, input.role);

  const updated = await memberRepo.updateMemberRole(
    input.orgId,
    input.memberId,
    input.role,
  );

  await emit("member.role_changed", {
    ...actorEnvelope(actor),
    memberId: updated.id,
    from: member.role,
    to: updated.role,
    active: member.status === "active",
  });

  return updated;
}

